    if not os.path.isdir(logdir):
        print(f"Error: {logdir} is not a directory", file=sys.stderr)
        sys.exit(1)

    # Collect candidate files matching the pattern:
    #   app.log  OR  app.log.N  OR  app.log.N.gz  (N = positive integer)
    entries = os.listdir(logdir)
    log_files = []
    for name in entries:
        if (name == 'app.log' or
            re.match(r'^app\.log\.\d+(\.gz)?$', name)):
            full_path = os.path.join(logdir, name)
            if os.path.isfile(full_path):
                log_files.append(full_path)

    # Parse all lines into records
    records = []
    for filepath in log_files:
        lines = read_lines(filepath)
        for line in lines:
            if not line.strip():
                continue
            result = parse_json_line(line) or parse_legacy_line(line)
            if result is None:
                continue

            ts_utc, user, request_id, status_int, latency_int = result
            records.append({
                'request_id': request_id,
                'ts_utc': ts_utc,
                'user': user,
                'status': status_int,
                'latency_ms': latency_int,
            })

    # For each request_id, keep only the attempt with the latest timestamp
    best = {}  # request_id -> record with latest ts
    for rec in records:
        rid = rec['request_id']
        if rid not in best or rec['ts_utc'] > best[rid]['ts_utc']:
            best[rid] = rec

    # Identify failed requests (status >= 500) and group by user
    user_fails = defaultdict(list)
    for rid, rec in best.items():
        if rec['status'] >= 500:
            user_fails[rec['user']].append(rec['latency_ms'])

    # Compute p95 using nearest-rank method: ceil(0.95 * n), 1-based
    results = []
    for user, latencies in user_fails.items():
        n = len(latencies)
        if n == 0:
            continue
        sorted_lat = sorted(latencies)
        idx = math.ceil(0.95 * n)  # 1-based index
        p95 = int(sorted_lat[idx - 1])  # convert to 0-based
        results.append((user, n, p95))

    # Sort by failures descending, then user ascending
    results.sort(key=lambda x: (-x[1], x[0]))

    # Output CSV
    print("user,failures,p95_ms")
    for user, fail_count, p95 in results:
        print(f"{user},{fail_count},{p95}")


